// Puzzle feed. Every day's puzzle lives in the codebase as src/puzzles/days/NNN.json
// (generated by tools/gen-days.mjs). Vite code-splits the glob, so the browser only
// downloads the file for the day being played. Games a day file does not define
// yet are filled from the sample puzzle, so the app never dead-ends while the
// generators are being built out.
import { SAMPLE_PUZZLE } from './sample.js';
import { validatePuzzle } from './schema.js';

const files = import.meta.glob('./days/*.json');
const cache = new Map();
const pad3 = (n) => String(n).padStart(3, '0');

/** True when a generated file exists for the day. */
export function hasDay(day) {
  return !!files['./days/' + pad3(day) + '.json'];
}

/** Resolve the puzzle for a challenge number. Always returns a valid puzzle. */
export async function loadPuzzle(day) {
  if (cache.has(day)) return cache.get(day);
  let partial = null;
  try {
    const load = files['./days/' + pad3(day) + '.json'];
    if (load) partial = (await load()).default;
  } catch (e) {
    partial = null;
  }
  const merged = mergeWithSample(partial, day);
  const p = validatePuzzle(merged).length ? { ...SAMPLE_PUZZLE, day } : merged;
  cache.set(day, p);
  return p;
}

export function mergeWithSample(partial, day) {
  return { ...SAMPLE_PUZZLE, ...(partial || {}), day };
}

export { SAMPLE_PUZZLE, validatePuzzle };
